08.773Z","http":200,"sha256":"069e0b17d7bc3b49d10101995633cd384d6037a57fdb4a5573bbb50a17485413","bytes":169961,"fact":"Dolfje Weerwolfje/Paul van Loon, white wolf and child in tree, Hugo van Look illustration, Leopold; NOT comicISBN9789025864118"},{"conflict":{"field":"Source Work heading","observed":"Dolfje Weerwolfje stripboek","decision":"Exact edition block/library are original novel; do not copy mixed Work heading or comic illustration credits."}}],"work_id":969100001,"language":"nl","bound_author_id":969300001,"text":"Dolfje ontdekt rond zijn zevende verjaardag dat hij bij volle maan in een weerwolfje verandert. Overdag is hij weer een gewone jongen, maar zijn nachtelijke gedaante levert vragen en onverwachte avonturen op. Zijn vriend Timmie probeert hem te helpen omgaan met het geheim. Dolfje wil niet buitengesloten worden en moet ontdekken wat deze verandering betekent voor zijn plaats binnen het gezin waarin hij opgroeit.","source_type":"official_catalog","source_name":"Bibliotheek.nl","source_url":"https://www.bibliotheek.nl/catalogus/titel.441426077.html/dolfje-weerwolfje/","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789403183404","key":{"id":969200002},"before":{"id":969200002,"title":"Revolusi","isbn_10":null,"isbn_13":"9789403183404","work_id":969100002,"cover_id":null,"language":null,"publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL32046626M"},"after":{"id":969200002,"title":"Revolusi","isbn_10":null,"isbn_13":"9789403183404","work_id":969100002,"cover_id":null,"language":"nld","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL32046626M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403183404","key":{"edition_id":969200002},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1364266/revolusi.html","checkedAt":"2026-10-