:200,"sha256":"e0f2747ab993fd7fe8e1763fb117703bc3b5cc254583dd1c9eb67a235dd41235","bytes":315038,"fact":"Revolusi/David Van Reybrouck, black branching motif/red title, De Bezige Bij mark; exact source hardback block"}],"work_id":969100002,"language":"nl","bound_author_id":969300002,"text":"David Van Reybrouck onderzoekt de Indonesische onafhankelijkheidsstrijd vanuit de ervaringen van mensen die de gebeurtenissen meemaakten. Interviews en historisch onderzoek verbinden de Japanse bezetting, de dekolonisatieoorlog en de internationale verhoudingen na de Tweede Wereldoorlog. Het boek plaatst de strijd niet alleen tegenover de Nederlandse koloniale macht, maar ook binnen bredere veranderingen in Azië en daarbuiten. Zo laat het verschillende perspectieven op het ontstaan van een onafhankelijke staat naast elkaar zien.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1364266/revolusi.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789029091015","key":{"id":969200003},"before":{"id":969200003,"title":"Leven en laten leven","isbn_10":null,"isbn_13":"9789029091015","work_id":969100003,"cover_id":null,"language":null,"publisher":"J.M. Meulenhoff","publish_date":null,"open_library_edition_id":"OL46531076M"},"after":{"id":969200003,"title":"Leven en laten leven","isbn_10":null,"isbn_13":"9789029091015","work_id":969100003,"cover_id":null,"language":"nld","publisher":"J.M. Meulenhoff","publish_date":null,"open_library_edition_id":"OL46531076M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789029091015","key":{"edition_id":969200003},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html","checkedAt":"2026-10-31","fact":"Exact Dutch paperbackISBN/date/cover and Arthur Ophof premise; ebook has differentISBN"},{"url":"http://data.bibliotheken.nl/id/nbt/p417062516","checkedAt":"2026-10-30T14:42:05.387Z","fact":"Retained National Bibliography exact DutchISBN/author/title identity"},{"url":"https://www.lannoo.com/nl-be/literatuur-romans/leven-en-laten-leven-9789029091015","checkedAt":"2026-10-31","fact":"Indexed official publisher confirms same Arthur Ophof novel; no fresh direct fetch or cover transplant"},{"url":"https://metadata.isbn.nl/ie_fcache/0000524092_Leven_en_laten_leven_0_0.jpg","checkedAt":"2026-10-31T19:30:13.793Z","http":200,"sha256":"406b63af0c24be00dcef1560d644514aa02ffaa191569992fab47e950dc85061","bytes":236066,"fact":"Leven en laten leven/Hendrik Groen, bread/tea illustration, Meulenhoff; exact paperback block, not a diary cover"}],"edition_id":969200003,"work_id":969100003,"bound_author_id":969300003,"bound_title":"Leven en laten leven","bound_language":"nld","bound_isbn13":"9789029091015","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000524092_Leven_en_laten_leven_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html"}},{"relation":"catalog_work_descriptions","ref":"description:1182:nl","key":{"work_id":969100003,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html","checkedAt":"2026-10-31","fact":"Exact Dutch paperbackISBN/date/cover and Arthur Ophof premise; ebook has differentISBN"},{"url":"http://data.bibliotheken.nl/id/nbt/p417062516","checkedAt":"2026-10-30T14:42:05.387Z","fact":"Retained National Bibliography exact DutchISBN/author/title identity"},{"url":"https://www.lannoo.com/nl-be/literatuur-romans/leven-en-laten-leven-9789029091015","checkedAt":"2026-10-31","fact":"Indexed official publisher confirms same Arthur Ophof novel; no fresh direct fetch or cover transplant"},{"url":"https://metadata.isbn.nl/ie_fcache/0000524092_Leven_en_laten_leven_0_0.jpg","checkedAt":"2026-10-31T19:30:13.793Z","http":200,"sha256":"406b63af0c24be00dcef1560d644514aa02ffaa191569992fab47e950dc85061","bytes":236066,"fact":"Leven en laten leven/Hendrik Groen, bread/tea illustration, Meulenhoff; exact paperback block, not a diary cover"}],"work_id":969100003,"language":"nl","bound_author_id":969300003,"text":"Arthur Ophof nadert de vijftig en merkt hoe weinig zijn dagelijkse bestaan lijkt op de reizen en avonturen waarvan hij droomde. Het woon-werkverkeer en een vastgelopen huwelijk bepalen zijn dagen; afspraken met vrienden bieden nog afwisseling. Wanneer hij zijn baan verliest en een ontslagvergoeding krijgt, ontstaat onverwacht ruimte voor verandering. Arthur gaat nadenken over een nieuw begin, maar moet ook onder ogen zien wat hij daarvoor achter zich zou laten.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1070391/leven-en-laten-leven.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789025440374","key":{"id":969200004},"before":{"id":969200004,"title":"Alles wat er was","isbn_10":null,"isbn_13":"9789025440374","work_id":969100004,"cover_id":null,"language":null,"publisher":"Atlas Contact","publish_date":null,"open_library_edition_id":"OL30959815M"},"after":{"id":969200004,"title":"Alles wat er was","isbn_10":null,"isbn_13":"9789025440374","work_id":969100004,"cover_id":null,"language":"nld","publisher":"Atlas Contact","publish_date":null,"open_library_edition_id":"OL30959815M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789025440374","key":{"edition_id":969200004},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T19:31:00Z","review_batch":"nl-followup-003-20261031","evidence":[{"url":"https://metadata.isbn.nl/123962/alles-wat-er-was.html","checkedAt":"2026-10-31","fact":"Exact2013DutchpaperbackISBN/date/cover and source narrative"},{"url":"https://www.biblio